def serialize(root):
    out = []
    def helper(node):
        if not node:
            out.append('#')
            return
        out.append(str(node.val))
        helper(node.left)
        helper(node.right)
    helper(root)
    return ','.join(out)

def deserialize(data):
    tokens = iter(data.split(','))
    def helper():
        val = next(tokens)
        if val == '#':
            return None
        node = Node(int(val))
        node.left = helper()
        node.right = helper()
        return node
    return helper()
```

Both are O(n), single-pass, no second traversal needed at all — the explicit null markers alone make one preorder sequence fully self-describing.
